import api from '../../services/api';
export default {
  name: 'StoreNotifications',
  data() {
    return {
      rows: []
    };
  },
  async created() {
    const {
      data
    } = await api.get('/store/notifications');
    this.rows = data;
  },
  methods: {
    async mark(n) {
      await api.post(`/store/notifications/${n.id}/read`);
      n.is_read = 1;
    }
  }
};
